package cn.zhuatech.iam;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class AccessSimulationApiTests{@Autowired MockMvc mvc;static final String BODY="""
 {"userNo":"E-1","asOf":"2026-09-20","roles":["PAYMENT_CREATE","PAYMENT_APPROVE"],"entitlements":[{"code":"BANK_ADMIN","privileged":true,"lastUsedDays":120,"expiresAt":"2026-09-01"}],"conflicts":[{"firstRole":"PAYMENT_CREATE","secondRole":"PAYMENT_APPROVE"}],"mfaEnabled":false,"justification":""}
 """;
 @Test void deniesSodConflictAndUnsafePrivilege()throws Exception{mvc.perform(post("/api/advanced/iam/access-simulation").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isOk()).andExpect(jsonPath("$.data.decision").value("DENY")).andExpect(jsonPath("$.data.sodConflicts").isNotEmpty()).andExpect(jsonPath("$.data.expiredEntitlements[0]").value("BANK_ADMIN"));}
 @Test void requiresAuthentication()throws Exception{mvc.perform(post("/api/advanced/iam/access-simulation").contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isUnauthorized());}}
